mapper.select:
SELECT * FROM public."TST_テスト情報" WHERE "家族学生ID" = #{familyStudentId}
AND "教科" = #{subject}
AND "区分" = #{kind}

    AND ("テスト番号" ILIKE CONCAT('%',#{keyword},'%')
         OR "テスト名称" ILIKE CONCAT('%',#{keyword},'%')
         OR COALESCE("詳細メモ",'') ILIKE CONCAT('%',#{keyword},'%'))

ORDER BY "試験日" DESC NULLS LAST, "テスト番号" DESC

mapper.update:
UPDATE public."TST_テスト情報"
   SET "テスト名称" = #{testName}, "教科" = #{subject}, "区分" = #{kind}, "試験日" = #{examDate},
       "得点数" = #{score}, "満点数" = #{fullScore}, "詳細メモ" = #{memo},
       "バージョン" = "バージョン" + 1, "更新ID" = #{operator}, "更新日時" = CURRENT_TIMESTAMP
 WHERE "家族学生ID" = #{familyStudentId} AND "テスト番号" = #{testNo}
   AND "バージョン" = #{beforeVersion}

mapper.select:
SELECT F.* FROM public."TST_テストファイル情報" F
  JOIN public."TST_テスト情報" M ON M."テストID" = F."テストID"
 WHERE M."家族学生ID" = #{familyStudentId} AND M."テスト番号" = #{testNo}
   AND F."テストファイルID" = #{fileId}

SELECT COUNT(*) FROM public."TST_テストファイル情報" F
  JOIN public."TST_テスト情報" M ON M."テストID" = F."テストID"
 WHERE M."家族学生ID" = #{familyStudentId} AND M."テスト番号" = #{testNo}

SELECT COALESCE(MAX(F."表示順"), -1) FROM public."TST_テストファイル情報" F
  JOIN public."TST_テスト情報" M ON M."テストID" = F."テストID"
 WHERE M."家族学生ID" = #{familyStudentId} AND M."テスト番号" = #{testNo}

mapper.update:
UPDATE public."TST_テストファイル情報" F
   SET "表示順" = #{displayOrder}, "コメント" = #{comment},
       "更新ID" = #{operator}, "更新日時" = CURRENT_TIMESTAMP
  FROM public."TST_テスト情報" M
 WHERE M."テストID" = F."テストID" AND M."家族学生ID" = #{familyStudentId}
   AND M."テスト番号" = #{testNo} AND F."テストファイルID" = #{fileId}

mapper.delete:
DELETE FROM public."TST_テストファイル情報" F
 USING public."TST_テスト情報" M
 WHERE M."テストID" = F."テストID" AND M."家族学生ID" = #{familyStudentId}
   AND M."テスト番号" = #{testNo} AND F."テストファイルID" = #{fileId}
